std::string input = "user@domain.com";
std::smatch results;
std::regex email_pattern(R"(\w+@\w+\.\w+)");

// Primary Overload: string object input
bool found = std::regex_search(input, results, email_pattern);

// Alternative Overload (Template instance based on iterators)
std::regex_search(
    input.cbegin(), input.cend(),
    results, email_pattern
);

// Accessing the capture group 0 (full match)
if (found) {
    std::string full = results.str(0);
}

// Result check (if not found, results is empty)
std::string no_match = "123";
bool fail = std::regex_search(no_match, results, std::regex("A"));
// fail == false; results.empty() == true;
